(function(root){
 const esc=x=>root.DL.esc(x),money=x=>root.DL.money(x);
 function label(s){return s?`<span class="store-label"><i style="background:${esc(s.color)}"></i><span data-no-i18n>${esc(s.name)}</span><small>${esc(s.platform)}</small>${s.archived?'<small>Archived</small>':''}</span>`:'—';}
 function periodFields(period='month',from='',to=''){return `<form data-period-form class="store-period"><label class="field"><span>Period</span><select name="period">${[['month','This month'],['last_month','Last month'],['30','Last 30 days'],['90','Last 90 days'],['year','This year'],['custom','Custom range']].map(([v,t])=>`<option value="${v}"${v===period?' selected':''}>${t}</option>`).join('')}</select></label>${period==='custom'?`<label class="field"><span>From</span><input name="from" type="date" value="${esc(from)}" required></label><label class="field"><span>To</span><input name="to" type="date" value="${esc(to)}" required></label>`:''}</form>`;}
 function table(stats,attribute='data-select-store'){
 const cells=r=>`<td data-label="Orders">${r.orders}</td><td data-label="Customers paid">${money(r.customersPaid)}</td><td data-label="Our total">${money(r.billed)}</td><td data-label="Your profit">${money(r.profit)}${r.missingSalePrice?`<small class="dim"><b data-no-i18n>${r.missingSalePrice}</b> <span>orders missing sale price</span></small>`:''}</td><td data-label="Share of profit"><progress max="100" value="${Math.max(0,Math.min(100,r.share||0))}"></progress><small data-no-i18n>${r.share||0}%</small></td>`;
 return `<div class="table-wrap"><table class="tbl stack store-performance"><thead><tr><th>Store</th><th>Orders</th><th>Customers paid</th><th>Our total</th><th>Your profit</th><th>Share of profit</th></tr></thead><tbody>${stats.rows.map(r=>`<tr class="click" ${attribute}="${r.id}" tabindex="0"><td>${label(r)}</td>${cells(r)}</tr>`).join('')}<tr class="store-total"><td>All stores</td>${cells({...stats.totals,share:stats.totals.profit?100:0})}</tr></tbody></table></div>`;
 }
 function form(store=null,clientId){return `<form class="form-grid" data-client-store-form="${store?.id||''}" data-client-id="${clientId}"><h3 class="full">${store?'Edit store':'Add store'}</h3><label class="field"><span>Store name</span><input name="storeName" maxlength="160" required value="${esc(store?.name)}"></label><label class="field"><span>Platform</span><select name="platform" required>${['Etsy','Shopify','Amazon','eBay','Other'].map(p=>`<option value="${p}"${p===(store?.platform||'Other')?' selected':''}>${p}</option>`).join('')}</select></label><label class="field full"><span>Store link <small>optional</small></span><input name="link" type="text" inputmode="url" placeholder="example.com or https://example.com" maxlength="1000" value="${esc(store?.link)}"></label><label class="field"><span>Colour</span><input name="color" type="color" value="${esc(store?.color||'#8b6e37')}"></label>${store?`<label class="field"><span>Archive store</span><input type="checkbox" name="archived"${store.archived?' checked':''}><small>Order history stays available.</small></label>`:''}<button class="btn btn-primary" type="submit">Save store</button><p class="form-msg" data-store-msg role="status" aria-live="polite"></p></form>`;}
 document.addEventListener('invalid',e=>{
  const f=e.target.closest('[data-client-store-form]');if(!f)return;
  f.querySelector('[data-store-msg]').textContent=e.target.name==='storeName'?'Enter a store name.':'Please check the highlighted field.';
 },true);
 root.DLClientStoreUI={label,periodFields,table,form};
})(window);
